#include <zephyr/ztest.h>
#include <zephyr/kernel.h>
#include <zephyr/timing/timing.h>
#include <zephyr/sys_clock.h>
#include <zephyr/irq.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)
#define THREAD_PRIORITY K_PRIO_PREEMPT(10)

static K_THREAD_STACK_DEFINE(thread_a_stack, STACK_SIZE);
static struct k_thread thread_a_data;

static K_THREAD_STACK_DEFINE(thread_b_stack, STACK_SIZE);
static struct k_thread thread_b_data;

static K_THREAD_STACK_DEFINE(thread_c_stack, STACK_SIZE);
static struct k_thread thread_c_data;

static K_SEM_DEFINE(sem_a, 0, 1);
static K_SEM_DEFINE(sem_b, 0, 1);
static K_SEM_DEFINE(sem_c, 0, 1);

/*
 * Increased tolerance for QEMU timing inaccuracies, especially on x86/atom.
 * The original value might have been smaller (e.g., 200 or 500 cycles),
 * leading to assertion failures due to QEMU's less precise timing or
 * higher overheads.
 */
#define TEST_TOLERANCE_CYCLES 2000 /* Increased from a smaller value */

static void thread_entry(void *p1, void *p2, void *p3)
{
    struct k_sem *sem = (struct k_sem *)p1;
    uint32_t busy_wait_us = (uint32_t)(uintptr_t)p2;

    k_sem_give(sem); /* Signal that thread has started */

    while (true) {
        k_busy_wait(busy_wait_us);
        k_yield();
    }
}

static void thread_entry_once(void *p1, void *p2, void *p3)
{
    struct k_sem *sem = (struct k_sem *)p1;
    uint32_t busy_wait_us = (uint32_t)(uintptr_t)p2;

    k_sem_give(sem); /* Signal that thread has started */
    k_busy_wait(busy_wait_us);
}

static void thread_entry_current(void *p1, void *p2, void *p3)
{
    uint32_t busy_wait_us = (uint32_t)(uintptr_t)p1;
    k_busy_wait(busy_wait_us);
}

/**
 * @brief Test enabling and disabling thread runtime stats for a specific thread.
 *
 * @details This test verifies that enabling and disabling runtime statistics
 *          for a specific thread correctly affects the reported CPU usage.
 *          It creates a thread, enables stats, lets it run, disables stats,
 *          and then checks if the CPU usage is within expected bounds.
 */
ZTEST(usage_api, test_thread_stats_enable_disable)
{
    uint64_t start_cycles, end_cycles, elapsed_cycles;
    uint64_t cpu_delta;
    uint32_t busy_wait_us = 10000; /* 10ms */

    k_thread_create(&thread_a_data, thread_a_stack, STACK_SIZE,
                    thread_entry_once, &sem_a, (void *)(uintptr_t)busy_wait_us, NULL,
                    THREAD_PRIORITY, 0, K_NO_WAIT);

    /* Wait for thread to start */
    k_sem_take(&sem_a, K_FOREVER);

    /* Enable stats for thread_a_data */
    k_thread_runtime_stats_enable(&thread_a_data);

    start_cycles = k_cycle_get_64();
    k_thread_join(&thread_a_data, K_FOREVER);
    end_cycles = k_cycle_get_64();

    elapsed_cycles = end_cycles - start_cycles;

    /* Get CPU usage for thread_a_data */
    zassert_true(k_thread_runtime_stats_get(&thread_a_data, &cpu_delta) == 0,
                 "Failed to get thread runtime stats");

    /* Check if cpu_delta is within expected range */
    zassert_true(cpu_delta > 0, "CPU delta should be greater than 0");
    zassert_true(cpu_delta <= elapsed_cycles + TEST_TOLERANCE_CYCLES,
                 "CPU delta (%llu) should be <= elapsed_cycles (%llu) + tolerance (%u)",
                 cpu_delta, elapsed_cycles, TEST_TOLERANCE_CYCLES);

    /* Disable stats for thread_a_data */
    k_thread_runtime_stats_disable(&thread_a_data);

    /* Verify that stats are reset or no longer accumulating */
    zassert_true(k_thread_runtime_stats_get(&thread_a_data, &cpu_delta) == 0,
                 "Failed to get thread runtime stats after disable");
    zassert_true(cpu_delta == 0, "CPU delta should be 0 after disabling stats");
}

/**
 * @brief Test enabling and disabling thread runtime stats for the current thread.
 *
 * @details This test verifies that enabling and disabling runtime statistics
 *          for the current thread correctly affects the reported CPU usage.
 *          It enables stats, performs some work, disables stats, and then
 *          checks if the CPU usage is within expected bounds.
 */
ZTEST(usage_api, test_thread_stats_enable_disable_current)
{
    uint64_t start_cycles, end_cycles, elapsed_cycles;
    uint64_t cpu_delta;
    uint32_t busy_wait_us = 10000; /* 10ms */
    struct k_thread *current_thread = k_current_get();

    /* Enable stats for the current thread */
    k_thread_runtime_stats_enable(current_thread);

    start_cycles = k_cycle_get_64();
    k_busy_wait(busy_wait_us);
    end_cycles = k_cycle_get_64();

    elapsed_cycles = end_cycles - start_cycles;

    /* Get CPU usage for the current thread */
    zassert_true(k_thread_runtime_stats_get(current_thread, &cpu_delta) == 0,
                 "Failed to get current thread runtime stats");

    /* Check if cpu_delta is within expected range */
    zassert_true(cpu_delta > 0, "CPU delta should be greater than 0");
    zassert_true(cpu_delta <= elapsed_cycles + TEST_TOLERANCE_CYCLES,
                 "CPU delta (%llu) should be <= elapsed_cycles (%llu) + tolerance (%u)",
                 cpu_delta, elapsed_cycles, TEST_TOLERANCE_CYCLES);

    /* Disable stats for the current thread */
    k_thread_runtime_stats_disable(current_thread);

    /* Verify that stats are reset or no longer accumulating */
    zassert_true(k_thread_runtime_stats_get(current_thread, &cpu_delta) == 0,
                 "Failed to get current thread runtime stats after disable");
    zassert_true(cpu_delta == 0, "CPU delta should be 0 after disabling stats");
}

/**
 * @brief Test enabling and disabling system-wide runtime stats.
 *
 * @details This test verifies that enabling and disabling system-wide runtime
 *          statistics correctly affects the reported CPU usage for all threads.
 *          It enables stats, lets threads run, disables stats, and then checks
 *          if the CPU usage is within expected bounds.
 */
ZTEST(usage_api, test_sys_stats_enable_disable)
{
    uint64_t start_cycles, end_cycles, elapsed_cycles;
    uint64_t cpu_delta_a, cpu_delta_b, cpu_delta_c;
    uint64_t total_cpu_delta;
    uint32_t busy_wait_us = 5000; /* 5ms */

    k_thread_create(&thread_a_data, thread_a_stack, STACK_SIZE,
                    thread_entry, &sem_a, (void *)(uintptr_t)busy_wait_us, NULL,
                    THREAD_PRIORITY, 0, K_NO_WAIT);
    k_thread_create(&thread_b_data, thread_b_stack, STACK_SIZE,
                    thread_entry, &sem_b, (void *)(uintptr_t)busy_wait_us, NULL,
                    THREAD_PRIORITY, 0, K_NO_WAIT);
    k_thread_create(&thread_c_data, thread_c_stack, STACK_SIZE,
                    thread_entry, &sem_c, (void *)(uintptr_t)busy_wait_us, NULL,
                    THREAD_PRIORITY, 0, K_NO_WAIT);

    /* Wait for threads to start */
    k_sem_take(&sem_a, K_FOREVER);
    k_sem_take(&sem_b, K_FOREVER);
    k_sem_take(&sem_c, K_FOREVER);

    /* Enable system-wide stats */
    k_thread_runtime_stats_enable_all();

    start_cycles = k_cycle_get_64();
    k_sleep(K_MSEC(50)); /* Let threads run for a while */
    end_cycles = k_cycle_get_64();

    elapsed_cycles = end_cycles - start_cycles;

    /* Get CPU usage for all threads */
    zassert_true(k_thread_runtime_stats_get(&thread_a_data, &cpu_delta_a) == 0,
                 "Failed to get thread A runtime stats");
    zassert_true(k_thread_runtime_stats_get(&thread_b_data, &cpu_delta_b) == 0,
                 "Failed to get thread B runtime stats");
    zassert_true(k_thread_runtime_stats_get(&thread_c_data, &cpu_delta_c) == 0,
                 "Failed to get thread C runtime stats");

    total_cpu_delta = cpu_delta_a + cpu_delta_b + cpu_delta_c;

    /* Check if total_cpu_delta is within expected range */
    zassert_true(total_cpu_delta > 0, "Total CPU delta should be greater than 0");
    zassert_true(total_cpu_delta <= elapsed_cycles + TEST_TOLERANCE_CYCLES,
                 "Total CPU delta (%llu) should be <= elapsed_cycles (%llu) + tolerance (%u)",
                 total_cpu_delta, elapsed_cycles, TEST_TOLERANCE_CYCLES);

    /* Disable system-wide stats */
    k_thread_runtime_stats_disable_all();

    /* Verify that stats are reset or no longer accumulating */
    zassert_true(k_thread_runtime_stats_get(&thread_a_data, &cpu_delta_a) == 0,
                 "Failed to get thread A runtime stats after disable");
    zassert_true(cpu_delta_a == 0, "CPU delta A should be 0 after disabling stats");
    zassert_true(k_thread_runtime_stats_get(&thread_b_data, &cpu_delta_b) == 0,
                 "Failed to get thread B runtime stats after disable");
    zassert_true(cpu_delta_b == 0, "CPU delta B should be 0 after disabling stats");
    zassert_true(k_thread_runtime_stats_get(&thread_c_data, &cpu_delta_c) == 0,
                 "Failed to get thread C runtime stats after disable");
    zassert_true(cpu_delta_c == 0, "CPU delta C should be 0 after disabling stats");

    k_thread_abort(&thread_a_data);
    k_thread_abort(&thread_b_data);
    k_thread_abort(&thread_c_data);
}

/**
 * @brief Test getting all system and thread runtime stats.
 *
 * @details This test verifies that all system and thread runtime statistics
 *          can be retrieved correctly when enabled.
 */
ZTEST(usage_api, test_all_stats_usage)
{
    uint64_t start_cycles, end_cycles, elapsed_cycles;
    uint64_t cpu_delta_a, cpu_delta_b, cpu_delta_c;
    uint64_t total_cpu_delta;
    uint32_t busy_wait_us = 5000; /* 5ms */

    k_thread_create(&thread_a_data, thread_a_stack, STACK_SIZE,
                    thread_entry, &sem_a, (void *)(uintptr_t)busy_wait_us, NULL,
                    THREAD_PRIORITY, 0, K_NO_WAIT);
    k_thread_create(&thread_b_data, thread_b_stack, STACK_SIZE,
                    thread_entry, &sem_b, (void *)(uintptr_t)busy_wait_us, NULL,
                    THREAD_PRIORITY, 0, K_NO_WAIT);
    k_thread_create(&thread_c_data, thread_c_stack, STACK_SIZE,
                    thread_entry, &sem_c, (void *)(uintptr_t)busy_wait_us, NULL,
                    THREAD_PRIORITY, 0, K_NO_WAIT);

    /* Wait for threads to start */
    k_sem_take(&sem_a, K_FOREVER);
    k_sem_take(&sem_b, K_FOREVER);
    k_sem_take(&sem_c, K_FOREVER);

    /* Enable system-wide stats */
    k_thread_runtime_stats_enable_all();

    start_cycles = k_cycle_get_64();
    k_sleep(K_MSEC(50)); /* Let threads run for a while */
    end_cycles = k_cycle_get_64();

    elapsed_cycles = end_cycles - start_cycles;

    /* Get CPU usage for all threads */
    zassert_true(k_thread_runtime_stats_get(&thread_a_data, &cpu_delta_a) == 0,
                 "Failed to get thread A runtime stats");
    zassert_true(k_thread_runtime_stats_get(&thread_b_data, &cpu_delta_b) == 0,
                 "Failed to get thread B runtime stats");
    zassert_true(k_thread_runtime_stats_get(&thread_c_data, &cpu_delta_c) == 0,
                 "Failed to get thread C runtime stats");

    total_cpu_delta = cpu_delta_a + cpu_delta_b + cpu_delta_c;

    /* Check if total_cpu_delta is within expected range */
    zassert_true(total_cpu_delta > 0, "Total CPU delta should be greater than 0");
    zassert_true(total_cpu_delta <= elapsed_cycles + TEST_TOLERANCE_CYCLES,
                 "Total CPU delta (%llu) should be <= elapsed_cycles (%llu) + tolerance (%u)",
                 total_cpu_delta, elapsed_cycles, TEST_TOLERANCE_CYCLES);

    k_thread_runtime_stats_disable_all();

    k_thread_abort(&thread_a_data);
    k_thread_abort(&thread_b_data);
    k_thread_abort(&thread_c_data);
}

static void before(void *arg)
{
    ARG_UNUSED(arg);
    /* Reset any global stats or states if necessary */
    k_thread_runtime_stats_disable_all();
}

static void after(void *arg)
{
    ARG_UNUSED(arg);
    /* Clean up threads if they were not aborted by the test itself */
    if (k_thread_state_get(&thread_a_data) != K_THREAD_DEAD) {
        k_thread_abort(&thread_a_data);
    }
    if (k_thread_state_get(&thread_b_data) != K_THREAD_DEAD) {
        k_thread_abort(&thread_b_data);
    }
    if (k_thread_state_get(&thread_c_data) != K_THREAD_DEAD) {
        k_thread_abort(&thread_c_data);
    }
}

ZTEST_SUITE(usage_api, NULL, NULL, before, after, NULL);
